CREATE OR REPLACE FUNCTION public.create_creator_page_event_draft(p_page_id uuid, p_event_id uuid, p_title text, p_category text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE p public.creator_page_drafts; v_community uuid; v_existing public.explore_events; v_delegated boolean; v_receipt public.creator_page_team_event_creations;
BEGIN
 SELECT * INTO p FROM public.creator_page_drafts WHERE id=p_page_id FOR UPDATE;
 IF auth.uid() IS NULL OR p.id IS NULL OR (p.owner_id<>auth.uid() AND NOT (p.page_kind='community' AND public.is_community_leader(p.id,auth.uid())) AND NOT public.creator_page_team_can_manage(p.id,'page_events'))
 OR NOT public.creator_page_audience_matches(coalesce(p.page_data->>'audience','everyone'),auth.uid()) THEN
  RAISE EXCEPTION 'Page unavailable' USING ERRCODE='42501'; END IF;
 IF p_event_id IS NULL OR coalesce(btrim(p_title),'')='' OR length(p_title)>120 OR coalesce(btrim(p_category),'')='' THEN
  RAISE EXCEPTION 'A title and category are required' USING ERRCODE='22023'; END IF;
 v_delegated := p.owner_id<>auth.uid() AND NOT (p.page_kind='community' AND public.is_community_leader(p.id,auth.uid()));
 SELECT * INTO v_receipt FROM public.creator_page_team_event_creations WHERE event_id=p_event_id;
 IF v_delegated THEN
  IF v_receipt.event_id IS NOT NULL AND (v_receipt.page_id<>p.id OR v_receipt.initiated_by<>auth.uid()
    OR v_receipt.page_owner_id<>p.owner_id OR v_receipt.requested_title<>btrim(p_title)
    OR v_receipt.requested_category<>btrim(p_category)) THEN
   RAISE EXCEPTION 'This saved event attempt does not match' USING ERRCODE='22023'; END IF;
 END IF;
 SELECT * INTO v_existing FROM public.explore_events WHERE id=p_event_id;
 IF v_delegated AND v_receipt.event_id IS NOT NULL THEN
  IF v_existing.id IS NOT NULL AND v_existing.host_user_id=p.owner_id
   AND EXISTS(SELECT 1 FROM public.creator_page_events WHERE event_id=p_event_id AND page_id=p.id) THEN RETURN p_event_id; END IF;
  RAISE EXCEPTION 'The original event is unavailable' USING ERRCODE='42501';
 END IF;
 IF v_existing.id IS NULL AND v_receipt.event_id IS NOT NULL THEN
  RAISE EXCEPTION 'The original event is unavailable' USING ERRCODE='42501'; END IF;
 IF v_existing.id IS NOT NULL THEN
  IF v_delegated THEN RAISE EXCEPTION 'Event unavailable' USING ERRCODE='42501'; END IF;
  IF EXISTS(SELECT 1 FROM public.creator_page_events WHERE event_id=p_event_id AND page_id=p.id) AND v_existing.host_user_id=auth.uid() THEN RETURN p_event_id; END IF;
  RAISE EXCEPTION 'Event unavailable' USING ERRCODE='42501';
 END IF;
 IF p.page_kind='community' THEN v_community:=public.ensure_creator_page_community(p.id); END IF;
 INSERT INTO public.explore_events(id,title,category,status,host_user_id,community_id,public_name)
 VALUES(p_event_id,btrim(p_title),btrim(p_category),'Draft',CASE WHEN v_delegated THEN p.owner_id ELSE auth.uid() END,v_community,p.page_data->>'name');
 INSERT INTO public.creator_page_events(event_id,page_id) VALUES(p_event_id,p.id);
 IF v_delegated THEN
  INSERT INTO public.creator_page_team_event_creations(event_id,page_id,initiated_by,page_owner_id,requested_title,requested_category)
   VALUES(p_event_id,p.id,auth.uid(),p.owner_id,btrim(p_title),btrim(p_category));
 END IF;
 RETURN p_event_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_creator_page_event_draft_with_categories(p_page_id uuid, p_event_id uuid, p_title text, p_categories text[])
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE a public.creator_page_event_category_attempts; result uuid; selected text[]; community boolean;
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in to continue' USING ERRCODE='42501'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_event_id::text,0));
 SELECT page_kind='community' INTO community FROM public.creator_page_drafts WHERE id=p_page_id;
 selected:=public.validate_event_categories(p_categories,coalesce(community,false));
 SELECT * INTO a FROM public.creator_page_event_category_attempts WHERE event_id=p_event_id;
 IF a.event_id IS NOT NULL THEN
  IF a.page_id<>p_page_id OR a.user_id<>auth.uid() OR a.title<>btrim(p_title) OR a.categories<>selected THEN RAISE EXCEPTION 'This saved event attempt does not match' USING ERRCODE='22023'; END IF;
  -- Recheck exact page authority; never replay category writes over later edits.
  RETURN public.create_creator_page_event_draft(p_page_id,p_event_id,p_title,selected[1]);
 END IF;
 IF EXISTS(SELECT 1 FROM public.explore_events WHERE id=p_event_id) THEN RAISE EXCEPTION 'Check the original event before continuing' USING ERRCODE='PT409'; END IF;
 result:=public.create_creator_page_event_draft(p_page_id,p_event_id,p_title,selected[1]);
 UPDATE public.explore_events SET categories=selected WHERE id=result;
 INSERT INTO public.creator_page_event_category_attempts VALUES(result,p_page_id,auth.uid(),btrim(p_title),selected);
 RETURN result;
END; $function$

CREATE OR REPLACE FUNCTION public.guard_event_category_continuity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE selected text[]; primary_category text; second_category text; legacy text; legacy_write boolean:=false;
BEGIN
  -- Older records and inserts retain their original single-category storage.
  IF cardinality(NEW.categories)=0 THEN RETURN NEW; END IF;
  IF TG_OP='UPDATE' THEN
    legacy:=OLD.category;
    legacy_write:=NEW.categories IS NOT DISTINCT FROM OLD.categories;
  END IF;
  IF legacy_write
      AND NEW.category IS DISTINCT FROM OLD.category THEN
    primary_category:=lower(btrim(NEW.category));
    IF NEW.community_id IS NOT NULL THEN
      IF primary_category='community' THEN
        selected:=ARRAY['community']||ARRAY(SELECT c FROM unnest(OLD.categories)c WHERE c<>'community' LIMIT 1);
      ELSE selected:=ARRAY[primary_category,'community']; END IF;
    ELSE
      second_category:=OLD.categories[2];
      selected:=ARRAY[primary_category];
      IF second_category IS NOT NULL AND second_category IS DISTINCT FROM primary_category THEN
        selected:=array_append(selected,second_category);
      END IF;
    END IF;
  ELSE selected:=NEW.categories;
  END IF;
  NEW.categories:=public.validate_event_categories(selected,NEW.community_id IS NOT NULL,legacy);
  -- An older caller's exact primary value is part of its saved receipt. Keep
  -- that value/casing while adding the required Community tag to its list.
  IF NOT legacy_write THEN NEW.category:=NEW.categories[1]; END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.operator_create_explore_event(p_title text, p_description text DEFAULT NULL::text, p_image_url text DEFAULT NULL::text, p_event_date text DEFAULT NULL::text, p_start_time timestamp with time zone DEFAULT NULL::timestamp with time zone, p_venue text DEFAULT NULL::text, p_venue_address text DEFAULT NULL::text, p_category text DEFAULT NULL::text, p_external_url text DEFAULT NULL::text, p_ticket_price text DEFAULT NULL::text, p_community_id uuid DEFAULT NULL::uuid, p_public_name text DEFAULT NULL::text, p_pin_to_chat boolean DEFAULT true, p_publish boolean DEFAULT true, p_end_time timestamp with time zone DEFAULT NULL::timestamp with time zone, p_description_blocks jsonb DEFAULT NULL::jsonb, p_confirmation_message text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_id uuid;
begin
  if v_uid is null then
    raise exception 'Not signed in';
  end if;
  if not (has_operator_grant(v_uid, 'event_host'::operator_track)
          or has_operator_grant(v_uid, 'community_leader'::operator_track)) then
    raise exception 'Not authorized';
  end if;
  if coalesce(btrim(p_title), '') = '' or char_length(p_title) > 120 then
    raise exception 'A title is required.';
  end if;
  if coalesce(btrim(p_category), '') = '' then
    raise exception 'Pick a category.';
  end if;
  -- S5: a dateless event can be a draft, never Live (LIZ COPY guard)
  if coalesce(p_publish, true) and coalesce(btrim(p_event_date), '') = '' then
    raise exception 'Pick a date.';
  end if;
  if p_community_id is not null
     and not is_community_leader(p_community_id, v_uid) then
    raise exception 'Not authorized for that community';
  end if;
  -- 75: when both times exist, order them (client-surfaced guard)
  if p_end_time is not null and p_start_time is not null
     and p_end_time <= p_start_time then
    raise exception 'The end has to come after the start.';
  end if;

  insert into explore_events (
    title, description, image_url, event_date, start_time, end_time, venue,
    venue_address, category, external_url, ticket_price,
    host_user_id, community_id, public_name, pin_to_chat, status,
    description_blocks, confirmation_message
  ) values (
    btrim(p_title),
    nullif(btrim(p_description), ''),
    nullif(btrim(p_image_url), ''),
    nullif(btrim(p_event_date), '')::date,
    p_start_time,
    p_end_time,
    nullif(btrim(p_venue), ''),
    nullif(btrim(p_venue_address), ''),
    nullif(btrim(p_category), ''),
    nullif(btrim(p_external_url), ''),
    nullif(btrim(p_ticket_price), '')::numeric,
    v_uid,
    p_community_id,
    nullif(btrim(p_public_name), ''),
    coalesce(p_pin_to_chat, true),
    case when coalesce(p_publish, true) then 'Live' else 'Draft' end,
    p_description_blocks,
    -- SQL-98: null (or blank) = omit, exactly like every other optional text
    nullif(btrim(p_confirmation_message), '')
  ) returning id into v_id;

  -- the chat is born at PUBLISH: a draft gets no topic
  if coalesce(p_publish, true) and p_community_id is not null then
    insert into community_topics (community_id, name, created_by, explore_event_id)
    values (p_community_id, left(btrim(p_title), 60), v_uid, v_id);
  end if;

  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.operator_create_explore_event_with_categories(p_title text, p_description text DEFAULT NULL::text, p_image_url text DEFAULT NULL::text, p_event_date text DEFAULT NULL::text, p_start_time timestamp with time zone DEFAULT NULL::timestamp with time zone, p_venue text DEFAULT NULL::text, p_venue_address text DEFAULT NULL::text, p_category text DEFAULT NULL::text, p_external_url text DEFAULT NULL::text, p_ticket_price text DEFAULT NULL::text, p_community_id uuid DEFAULT NULL::uuid, p_public_name text DEFAULT NULL::text, p_pin_to_chat boolean DEFAULT true, p_publish boolean DEFAULT true, p_end_time timestamp with time zone DEFAULT NULL::timestamp with time zone, p_description_blocks jsonb DEFAULT NULL::jsonb, p_confirmation_message text DEFAULT NULL::text, p_categories text[] DEFAULT NULL::text[])
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE result uuid; selected text[]; BEGIN
selected:=public.validate_event_categories(coalesce(p_categories,ARRAY[p_category]),p_community_id IS NOT NULL);
result:=public.operator_create_explore_event(p_title=>p_title,p_description=>p_description,p_image_url=>p_image_url,p_event_date=>p_event_date,p_start_time=>p_start_time,p_venue=>p_venue,p_venue_address=>p_venue_address,p_category=>p_category,p_external_url=>p_external_url,p_ticket_price=>p_ticket_price,p_community_id=>p_community_id,p_public_name=>p_public_name,p_pin_to_chat=>p_pin_to_chat,p_publish=>p_publish,p_end_time=>p_end_time,p_description_blocks=>p_description_blocks,p_confirmation_message=>p_confirmation_message);
UPDATE public.explore_events SET categories=selected WHERE id=result;
RETURN result;
END;
$function$

CREATE OR REPLACE FUNCTION public.operator_set_event_offer_type(p_event_id uuid, p_offer_type text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE e public.explore_events; v_uid uuid:=auth.uid();
BEGIN
 SELECT * INTO e FROM public.explore_events WHERE id=p_event_id FOR UPDATE;
 IF v_uid IS NULL OR e.id IS NULL OR NOT coalesce((
  ((e.host_user_id=v_uid OR (e.community_id IS NOT NULL AND public.is_community_leader(e.community_id,v_uid)))
   AND public.creator_event_owner_is_eligible(e.id))
  OR public.is_admin(v_uid) OR public.has_role(v_uid,'admin'::public.app_role)),false) THEN
  RAISE EXCEPTION 'Event unavailable' USING ERRCODE='42501'; END IF;
 -- Match the four currently supported choices; stored enum labels for future
 -- mechanics are retained from the inherited source, not activated here.
 IF p_offer_type IS NULL OR p_offer_type NOT IN('free_event','ticketed_event','course','drop_in') THEN
  RAISE EXCEPTION 'Choose a supported event offer' USING ERRCODE='22023'; END IF;
 UPDATE public.explore_events SET offer_type=p_offer_type::public.event_offer_type,updated_at=now() WHERE id=e.id;
 RETURN jsonb_build_object('event_id',e.id,'offer_type',p_offer_type);
END;
$function$

CREATE OR REPLACE FUNCTION public.operator_set_event_ticket_capacity(p_event_id uuid, p_ticket_capacity integer DEFAULT NULL::integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_row record;
begin
  if v_uid is null then
    raise exception 'Not signed in';
  end if;
  select id, host_user_id, community_id into v_row
  from explore_events where id = p_event_id;
  if v_row.id is null then
    raise exception 'Event not found';
  end if;
  if not coalesce((v_row.host_user_id = v_uid
          or (v_row.community_id is not null and is_community_leader(v_row.community_id, v_uid))),false) then
    raise exception 'Not authorized';
  end if;
  if p_ticket_capacity is not null and p_ticket_capacity <= 0 then
    raise exception 'Capacity has to be at least 1, or left blank for unlimited.';
  end if;

  update explore_events set
    ticket_capacity = p_ticket_capacity,
    updated_at = now()
  where id = p_event_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.operator_set_explore_event_coords(p_event_id uuid, p_latitude double precision DEFAULT NULL::double precision, p_longitude double precision DEFAULT NULL::double precision)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_row record;
begin
  if v_uid is null then
    raise exception 'Not signed in';
  end if;
  select id, host_user_id, community_id into v_row
  from explore_events where id = p_event_id;
  if v_row.id is null then
    raise exception 'Event not found';
  end if;
  if not (v_row.host_user_id = v_uid
          or (v_row.community_id is not null and is_community_leader(v_row.community_id, v_uid))
          or public.creator_page_team_event_can_manage(p_event_id)) then
    raise exception 'Not authorized';
  end if;
  -- both or neither: a lone latitude is never a place
  if (p_latitude is null) <> (p_longitude is null) then
    raise exception 'Coordinates travel as a pair';
  end if;

  update explore_events set
    latitude = p_latitude,
    longitude = p_longitude,
    updated_at = now()
  where id = p_event_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.operator_update_explore_event(p_event_id uuid, p_title text, p_description text DEFAULT NULL::text, p_image_url text DEFAULT NULL::text, p_event_date text DEFAULT NULL::text, p_start_time timestamp with time zone DEFAULT NULL::timestamp with time zone, p_venue text DEFAULT NULL::text, p_venue_address text DEFAULT NULL::text, p_category text DEFAULT NULL::text, p_external_url text DEFAULT NULL::text, p_ticket_price text DEFAULT NULL::text, p_public_name text DEFAULT NULL::text, p_pin_to_chat boolean DEFAULT true, p_status text DEFAULT NULL::text, p_end_time timestamp with time zone DEFAULT NULL::timestamp with time zone, p_description_blocks jsonb DEFAULT NULL::jsonb, p_confirmation_message text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_row record;
  v_page uuid;
  v_readiness jsonb;
begin
  if v_uid is null then
    raise exception 'Not signed in';
  end if;
  select id, host_user_id, community_id, status into v_row
  from explore_events where id = p_event_id FOR UPDATE;
  if v_row.id is null then
    raise exception 'Event not found';
  end if;
  if not coalesce((v_row.host_user_id = v_uid
          or (v_row.community_id is not null and is_community_leader(v_row.community_id, v_uid))
          or public.creator_page_team_event_can_manage(p_event_id)),false) then
    raise exception 'Not authorized';
  end if;
  -- New page teammates have content authority only. Existing owner and
  -- legacy co-leader financial/cancellation paths remain unchanged.
  if not (coalesce(v_row.host_user_id = v_uid,false)
          or (v_row.community_id is not null and is_community_leader(v_row.community_id,v_uid)))
     and p_status='Cancelled' then
    select page_id into v_page from public.creator_page_events where event_id=p_event_id;
    v_readiness:=public.creator_page_event_readiness(v_page,p_event_id);
    if p_status='Cancelled' and (v_readiness->>'cancellation_requires_refunds')::boolean then
      raise exception 'The event organizer needs to complete ticket refunds before this event can be canceled.' using errcode='PT409';
    end if;
  end if;
  if coalesce(btrim(p_title), '') = '' or char_length(p_title) > 120 then
    raise exception 'A title is required.';
  end if;
  if p_status is not null and p_status not in ('Live', 'Completed', 'Cancelled') then
    raise exception 'Invalid status';
  end if;
  if v_row.status = 'Draft' and p_status in ('Completed', 'Cancelled') then
    -- LIZ COPY
    raise exception 'This one is still a draft. Publish it or keep shaping it.';
  end if;
  if coalesce(btrim(p_category), '') = '' then
    raise exception 'Pick a category.';
  end if;
  -- S5: Live (asked for or carried through the full overwrite) keeps a date;
  -- this also blocks blanking the date on a Live event. Cancel/complete of a
  -- dateless legacy row stays allowed. (LIZ COPY guard)
  if coalesce(p_status, v_row.status) = 'Live'
     and coalesce(btrim(p_event_date), '') = '' then
    raise exception 'Pick a date.';
  end if;
  -- 75: when both times exist, order them (client-surfaced guard)
  if p_end_time is not null and p_start_time is not null
     and p_end_time <= p_start_time then
    raise exception 'The end has to come after the start.';
  end if;
  -- SQL-96: the friendly cap, ahead of the CHECK (LIZ COPY)
  if p_confirmation_message is not null and char_length(p_confirmation_message) > 2500 then
    raise exception 'Keep the confirmation note under 2500 characters.';
  end if;

  update explore_events set
    title = btrim(p_title),
    description = nullif(btrim(p_description), ''),
    image_url = nullif(btrim(p_image_url), ''),
    event_date = nullif(btrim(p_event_date), '')::date,
    start_time = p_start_time,
    end_time = p_end_time,
    venue = nullif(btrim(p_venue), ''),
    venue_address = nullif(btrim(p_venue_address), ''),
    category = nullif(btrim(p_category), ''),
    external_url = nullif(btrim(p_external_url), ''),
    ticket_price = nullif(btrim(p_ticket_price), '')::numeric,
    public_name = nullif(btrim(p_public_name), ''),
    pin_to_chat = coalesce(p_pin_to_chat, true),
    status = coalesce(p_status, status),
    -- 77's DOCUMENTED DEVIATION from full-overwrite: null = leave the rich
    -- body untouched (it is large and easy to lose); [] = clear it
    description_blocks = coalesce(p_description_blocks, description_blocks),
    -- SQL-96, same deviation on purpose: null = keep, '' = clear
    confirmation_message = case
      when p_confirmation_message is null then confirmation_message
      else nullif(btrim(p_confirmation_message), '')
    end,
    updated_at = now()
  where id = p_event_id;

  -- Validate the actual submitted fields before making any page event live.
  -- Failure rolls back the full overwrite above. Unmapped standalone events
  -- keep their original publication routine; all page publishers share this gate.
  if p_status='Live' then
    select page_id into v_page from public.creator_page_events where event_id=p_event_id;
    if v_page is not null then
      if v_row.status not in ('Draft','Live') then
        raise exception 'This event cannot be published' using errcode='PT409';
      end if;
      if v_row.status='Draft' then
        v_readiness:=public.creator_page_event_readiness(v_page,p_event_id);
        if not (v_readiness->>'publish_ready')::boolean then
          raise exception 'Finish the event publishing setup before publishing.' using errcode='PT409',detail=v_readiness->>'publish_reason';
        end if;
      end if;
    end if;
  end if;

  -- publish flip: the event chat is born NOW; the partial unique index
  -- (one topic per event) makes a double-publish a clean no-op
  if v_row.status = 'Draft' and p_status = 'Live' and v_row.community_id is not null then
    insert into community_topics (community_id, name, created_by, explore_event_id)
    values (v_row.community_id, left(btrim(p_title), 60), v_uid, p_event_id)
    on conflict (explore_event_id) where explore_event_id is not null do nothing;
  end if;

  update community_topics
  set name = left(btrim(p_title), 60),
      archived = archived or coalesce(p_status, '') in ('Cancelled', 'Completed')
  where explore_event_id = p_event_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.operator_update_explore_event_with_categories(p_event_id uuid, p_title text, p_description text DEFAULT NULL::text, p_image_url text DEFAULT NULL::text, p_event_date text DEFAULT NULL::text, p_start_time timestamp with time zone DEFAULT NULL::timestamp with time zone, p_venue text DEFAULT NULL::text, p_venue_address text DEFAULT NULL::text, p_category text DEFAULT NULL::text, p_external_url text DEFAULT NULL::text, p_ticket_price text DEFAULT NULL::text, p_public_name text DEFAULT NULL::text, p_pin_to_chat boolean DEFAULT true, p_status text DEFAULT NULL::text, p_end_time timestamp with time zone DEFAULT NULL::timestamp with time zone, p_description_blocks jsonb DEFAULT NULL::jsonb, p_confirmation_message text DEFAULT NULL::text, p_categories text[] DEFAULT NULL::text[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE selected text[]; community boolean; legacy text; BEGIN
SELECT category INTO legacy FROM public.explore_events WHERE id=p_event_id;
PERFORM public.operator_update_explore_event(p_event_id=>p_event_id,p_title=>p_title,p_description=>p_description,p_image_url=>p_image_url,p_event_date=>p_event_date,p_start_time=>p_start_time,p_venue=>p_venue,p_venue_address=>p_venue_address,p_category=>p_category,p_external_url=>p_external_url,p_ticket_price=>p_ticket_price,p_public_name=>p_public_name,p_pin_to_chat=>p_pin_to_chat,p_status=>p_status,p_end_time=>p_end_time,p_description_blocks=>p_description_blocks,p_confirmation_message=>p_confirmation_message);
SELECT community_id IS NOT NULL INTO community FROM public.explore_events WHERE id=p_event_id;
selected:=public.validate_event_categories(coalesce(p_categories,ARRAY[p_category]),coalesce(community,false),legacy);
UPDATE public.explore_events SET categories=selected WHERE id=p_event_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_event_categories(p_categories text[], p_community boolean DEFAULT false, p_legacy text DEFAULT NULL::text)
 RETURNS text[]
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
DECLARE result text[];
BEGIN
 IF p_categories IS NULL OR cardinality(p_categories) NOT BETWEEN 1 AND 2 OR array_ndims(p_categories)<>1
 OR EXISTS(SELECT 1 FROM unnest(p_categories) c WHERE c IS NULL OR c NOT IN('music','comedy','nightlife','food and drink','art','fitness','outdoors','community','film','markets','gaming','business & networking','just for fun','other','fitness and outdoors') AND c IS DISTINCT FROM lower(p_legacy))
 OR (SELECT count(DISTINCT c) FROM unnest(p_categories)c)<>cardinality(p_categories)
 THEN RAISE EXCEPTION 'Choose one or two different categories' USING ERRCODE='22023'; END IF;
 result:=p_categories;
 IF p_community AND NOT 'community'=ANY(result) THEN result:=array_prepend('community',result); END IF;
 IF cardinality(result)>2 THEN RAISE EXCEPTION 'Community events include Community and one optional category' USING ERRCODE='22023'; END IF;
 RETURN result;
END; $function$

