CREATE OR REPLACE FUNCTION public.creator_page_event_publication_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_page uuid; p public.creator_page_drafts; v_cleanup boolean := false;
BEGIN
 SELECT page_id INTO v_page FROM public.creator_page_events WHERE event_id=NEW.id;
 IF v_page IS NULL AND NEW.community_id IS NOT NULL THEN
  SELECT id INTO v_page FROM public.creator_page_drafts WHERE id=NEW.community_id;
  IF v_page IS NULL THEN SELECT page_id INTO v_page FROM public.creator_page_publications WHERE page_id=NEW.community_id; END IF;
 END IF;
 IF v_page IS NULL THEN RETURN NEW; END IF; -- Existing unmapped events unchanged.
 SELECT * INTO p FROM public.creator_page_drafts WHERE id=v_page FOR SHARE;
 IF TG_OP='UPDATE' AND (NEW.community_id IS DISTINCT FROM OLD.community_id OR NEW.host_user_id IS DISTINCT FROM OLD.host_user_id
  OR NEW.owner_type IS DISTINCT FROM OLD.owner_type OR NEW.owner_user_id IS DISTINCT FROM OLD.owner_user_id
  OR NEW.owner_community_id IS DISTINCT FROM OLD.owner_community_id) THEN
  -- Preserve established FK cleanup/re-homing when an account/community is
  -- actually deleted. A client cannot use nulls to detach a still-existing owner.
  v_cleanup := NEW.owner_type IS NOT DISTINCT FROM OLD.owner_type
   AND (NEW.host_user_id IS NOT DISTINCT FROM OLD.host_user_id OR (NEW.host_user_id IS NULL AND NOT EXISTS(SELECT 1 FROM auth.users WHERE id=OLD.host_user_id)))
   AND (NEW.community_id IS NOT DISTINCT FROM OLD.community_id OR (NEW.community_id IS NULL AND NOT EXISTS(SELECT 1 FROM public.communities WHERE id=OLD.community_id)))
   AND (NEW.owner_user_id IS NOT DISTINCT FROM OLD.owner_user_id OR (NEW.owner_user_id IS NULL AND NOT EXISTS(SELECT 1 FROM auth.users WHERE id=OLD.owner_user_id)))
   AND (NEW.owner_community_id IS NOT DISTINCT FROM OLD.owner_community_id OR (NEW.owner_community_id IS NULL AND NOT EXISTS(SELECT 1 FROM public.communities WHERE id=OLD.owner_community_id)));
  IF NOT v_cleanup THEN RAISE EXCEPTION 'The saved event must keep its page and creator' USING ERRCODE='PT409'; END IF;
 END IF;
 -- v_cleanup requires the referenced parent to have actually been deleted.
 -- Keep the existing FK action possible; ordinary updates still require publication.
 IF NOT v_cleanup AND NEW.status='Live' AND NOT EXISTS(SELECT 1 FROM public.creator_page_publications pub WHERE pub.page_id=v_page
   AND (pub.page_kind='organization' OR EXISTS(SELECT 1 FROM public.communities c WHERE c.id=v_page AND c.status='active'))) THEN
  RAISE EXCEPTION 'Publish the approved page before its event' USING ERRCODE='PT409'; END IF;
 IF NOT v_cleanup AND auth.uid() IS NOT NULL AND NOT public.creator_page_audience_matches(
  coalesce((SELECT audience FROM public.creator_page_publications WHERE page_id=v_page),p.page_data->>'audience','everyone'),auth.uid()) THEN
  RAISE EXCEPTION 'Page unavailable' USING ERRCODE='42501'; END IF;
 RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.creator_page_event_validate_media()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE ref text; expected text; b jsonb;
BEGIN
 IF NEW.image_url LIKE 'creator-event-media:%' THEN
  ref:=substr(NEW.image_url,length('creator-event-media:')+1);
  IF NOT EXISTS(SELECT 1 FROM public.creator_page_event_media m WHERE m.event_id=NEW.id AND m.object_name=ref AND m.purpose='cover' AND m.ready_at IS NOT NULL AND m.abandoned_at IS NULL) THEN RAISE EXCEPTION 'Cover upload is not confirmed for this event' USING ERRCODE='22023'; END IF;
 END IF;
 FOR b IN SELECT value FROM jsonb_array_elements(CASE WHEN jsonb_typeof(NEW.description_blocks)='array' THEN NEW.description_blocks ELSE '[]'::jsonb END) LOOP
  FOREACH expected IN ARRAY ARRAY['path','poster'] LOOP
   ref:=b->>expected;
   IF ref LIKE '%/private-%' THEN
    IF NOT EXISTS(SELECT 1 FROM public.creator_page_event_media m WHERE m.event_id=NEW.id AND m.object_name=ref
     AND m.purpose=CASE WHEN expected='poster' THEN 'poster' ELSE b->>'type' END AND m.ready_at IS NOT NULL AND m.abandoned_at IS NULL) THEN RAISE EXCEPTION 'Media upload is not confirmed for this event' USING ERRCODE='22023'; END IF;
   END IF;
  END LOOP;
 END LOOP;
 RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_event_category_continuity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE selected text[]; primary_category text; second_category text; legacy text; legacy_write boolean:=false;
BEGIN
  -- Older records and inserts retain their original single-category storage.
  IF cardinality(NEW.categories)=0 THEN RETURN NEW; END IF;
  IF TG_OP='UPDATE' THEN
    legacy:=OLD.category;
    legacy_write:=NEW.categories IS NOT DISTINCT FROM OLD.categories;
  END IF;
  IF legacy_write
      AND NEW.category IS DISTINCT FROM OLD.category THEN
    primary_category:=lower(btrim(NEW.category));
    IF NEW.community_id IS NOT NULL THEN
      IF primary_category='community' THEN
        selected:=ARRAY['community']||ARRAY(SELECT c FROM unnest(OLD.categories)c WHERE c<>'community' LIMIT 1);
      ELSE selected:=ARRAY[primary_category,'community']; END IF;
    ELSE
      second_category:=OLD.categories[2];
      selected:=ARRAY[primary_category];
      IF second_category IS NOT NULL AND second_category IS DISTINCT FROM primary_category THEN
        selected:=array_append(selected,second_category);
      END IF;
    END IF;
  ELSE selected:=NEW.categories;
  END IF;
  NEW.categories:=public.validate_event_categories(selected,NEW.community_id IS NOT NULL,legacy);
  -- An older caller's exact primary value is part of its saved receipt. Keep
  -- that value/casing while adding the required Community tag to its list.
  IF NOT legacy_write THEN NEW.category:=NEW.categories[1]; END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.tg_event_owner_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_reason    text;
  v_committed boolean;
BEGIN
  IF NEW.owner_type IS NOT DISTINCT FROM OLD.owner_type
     AND NEW.owner_user_id IS NOT DISTINCT FROM OLD.owner_user_id
     AND NEW.owner_community_id IS NOT DISTINCT FROM OLD.owner_community_id THEN
    RETURN NEW;
  END IF;

  -- caller-declared intent, read from the transaction (set outside any function,
  -- so it is visible here)
  v_reason := nullif(btrim(coalesce(current_setting('washedup.owner_change_reason', true), '')), '');

  -- (i) re-home after a foreign key cascade nulled the owner out from under us
  IF NEW.owner_type = 'community' AND NEW.owner_community_id IS NULL THEN
    IF NEW.host_user_id IS NOT NULL THEN
      NEW.owner_type    := 'organization';
      NEW.owner_user_id := NEW.host_user_id;
    ELSE
      NEW.owner_type    := 'platform';
      NEW.owner_user_id := NULL;
    END IF;
    v_reason := 'automatic: owning community deleted, event re-homed';
  ELSIF NEW.owner_type = 'organization' AND NEW.owner_user_id IS NULL THEN
    NEW.owner_type         := 'platform';
    NEW.owner_community_id := NULL;
    v_reason := 'automatic: owning user deleted, event re-homed to platform';
  END IF;

  SELECT EXISTS (
           SELECT 1 FROM public.ticket_orders o
            WHERE o.event_id = NEW.id AND o.status IN ('paid', 'refunded')
         )
      OR EXISTS (
           SELECT 1 FROM public.explore_event_rsvps r
            WHERE r.explore_event_id = NEW.id AND r.status = 'going'
         )
    INTO v_committed;

  -- (ii) invariant 2
  IF v_reason IS NULL AND v_committed THEN
    RAISE EXCEPTION
      'Event % has committed guests; an owner change must be an explicit administrative action. Set washedup.owner_change_reason in this transaction first.',
      NEW.id
      USING ERRCODE = 'check_violation';
  END IF;

  -- (iii) audit
  INSERT INTO public.event_owner_changes (
    event_id, changed_by, actor_db_role,
    previous_owner_type, previous_owner_user_id, previous_owner_community_id,
    new_owner_type, new_owner_user_id, new_owner_community_id,
    reason, had_committed_guests
  ) VALUES (
    NEW.id, auth.uid(), current_user,
    OLD.owner_type, OLD.owner_user_id, OLD.owner_community_id,
    NEW.owner_type, NEW.owner_user_id, NEW.owner_community_id,
    coalesce(v_reason, 'unspecified: no committed guests at change time'),
    v_committed
  );

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.tg_event_owner_derive()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Build 35 code that sets ownership explicitly is left alone.
  IF NEW.owner_type IS NOT NULL THEN
    RETURN NEW;
  END IF;

  -- Same precedence as the section 2 backfill, so a row inserted one second
  -- after this migration applies is classified identically to one inserted a
  -- year before it.
  IF NEW.community_id IS NOT NULL THEN
    NEW.owner_type         := 'community';
    NEW.owner_community_id := NEW.community_id;
    NEW.owner_user_id      := NULL;
  ELSIF NEW.host_user_id IS NOT NULL THEN
    NEW.owner_type         := 'organization';
    NEW.owner_user_id      := NEW.host_user_id;
    NEW.owner_community_id := NULL;
  ELSE
    NEW.owner_type         := 'platform';
    NEW.owner_user_id      := NULL;
    NEW.owner_community_id := NULL;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.tg_explore_events_keep_paid_end_time()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.end_time is null and old.end_time is not null and exists (
    select 1 from public.ticket_tiers t
    where t.event_id = new.id and t.price_cents > 0
  ) then
    raise exception 'end_time cannot be cleared while the event has paid tiers';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.tg_explore_events_valid_blocks()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_block jsonb;
  v_type text;
  v_faq_seen boolean := false;
begin
  if new.description_blocks is null then
    return new;
  end if;
  if jsonb_typeof(new.description_blocks) <> 'array' then
    raise exception 'description_blocks must be a json array';
  end if;
  if jsonb_array_length(new.description_blocks) > 30 then
    raise exception 'description_blocks holds at most 30 blocks';
  end if;
  for v_block in select jsonb_array_elements(new.description_blocks)
  loop
    if jsonb_typeof(v_block) <> 'object' then
      raise exception 'every block must be a json object';
    end if;
    v_type := v_block->>'type';
    if v_type = 'text' then
      -- 7-21 fix: a MISSING content key made this whole condition NULL and
      -- the raise skipped (the 66-catch bug class); presence is now
      -- required explicitly
      if not (v_block ? 'content')
         or jsonb_typeof(v_block->'content') <> 'string'
         or char_length(v_block->>'content') not between 1 and 5000 then
        raise exception 'a text block needs content, 1..5000 chars';
      end if;
    elsif v_type in ('image', 'video') then
      -- 7-21 fixes carried verbatim: key presence required, the folder pin
      -- rejects "..", a trailing slash, and empty path segments. 77 adds
      -- the video branch under the SAME path law plus the v1 mp4 rule.
      if not (v_block ? 'path')
         or jsonb_typeof(v_block->'path') <> 'string'
         or char_length(v_block->>'path') > 500
         or (v_block->>'path') not like (new.id::text || '/%')
         or (v_block->>'path') like '%..%'
         or (v_block->>'path') like '%/'
         or (v_block->>'path') like '%//%' then
        raise exception 'a media block''s path must live under this event''s own folder';
      end if;
      if v_type = 'video' and lower(v_block->>'path') not like '%.mp4' then
        raise exception 'a video block is hosted mp4 in v1';
      end if;
      if v_block ? 'alt' and (jsonb_typeof(v_block->'alt') <> 'string'
         or char_length(v_block->>'alt') > 300) then
        raise exception 'a media alt is a string of at most 300 chars';
      end if;
    elsif v_type = 'faq' then
      if v_faq_seen then
        raise exception 'at most one faq marker per page';
      end if;
      v_faq_seen := true;
    else
      raise exception 'unknown block type %', coalesce(v_type, '(none)');
    end if;
  end loop;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.tg_explore_events_valid_timezone()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  begin
    perform now() at time zone new.timezone;
  exception when others then
    raise exception '"%" is not a valid IANA timezone', new.timezone;
  end;
  return new;
end;
$function$
